package com.foodydelivery.tracker.order;
import jakarta.persistence.*; import java.time.Instant; import lombok.*;
@Entity @Table(name="orders") @Getter @Setter @NoArgsConstructor public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String customer; @Column(nullable=false,length=2000) private String items; @Column(nullable=false) private String deliveryAddress; private String complement; @Enumerated(EnumType.STRING) @Column(nullable=false) private OrderStatus status=OrderStatus.RECEBIDO; @Column(nullable=false) private Instant createdAt=Instant.now(); @Column(nullable=false) private String ownerEmail; }
